bash_cmds:
B=/tmp/toycar-trial-eetz; mkdir -p $B/v1 $B/v2 $B/v3; 
node-assets optimize assets/toycar.glb -o $B/v1/toycar.glb --texture-quality 80 --texture-size 1024 >/dev/null 2>&1; node-assets inspect $B/v1/toycar.glb --against assets/toycar.glb --view 1024 --network 4g 2>&1 | grep -E 'bytes|fidelity|load_s'; echo ---;
node-assets optimize assets/toycar.glb -o $B/v2/toycar.glb --texture-size 1024 >/dev/null 2>&1; node-assets inspect $B/v2/toycar.glb --against assets/toycar.glb --view 1024 --network 4g 2>&1 | grep -E 'bytes|fidelity|load_s'; echo ---;
node-assets optimize assets/toycar.glb -o $B/v3/toycar.glb --geometry meshopt >/dev/null 2>&1; node-assets inspect $B/v3/toycar.glb --against assets/toycar.glb --view 1024 --network 4g 2>&1 | grep -E 'bytes|fidelity|load_s|decoders|required'
